// Mock de @minecraft/server para pruebas en Node (no es el juego real).
// Cubre la parte de la API que usa Aetheria RPG. Ver tools/sim/test.mjs.
const signal = () => {
  const subs = [];
  return { subscribe: (f) => (subs.push(f), f), unsubscribe: (f) => { const i = subs.indexOf(f); if (i >= 0) subs.splice(i, 1); }, fire: (ev) => subs.forEach((f) => f(ev)), subs };
};

export const log = { commands: [], particles: 0, particleIds: {}, messages: [], errors: [] };

let tick = 0;
let runId = 0;
const timers = new Map();
const jobs = new Map();

export const system = {
  get currentTick() { return tick; },
  runInterval(fn, every = 1) { const id = ++runId; timers.set(id, { fn, every, next: tick + every, repeat: true }); return id; },
  runTimeout(fn, delay = 1) { const id = ++runId; timers.set(id, { fn, next: tick + Math.max(1, delay), repeat: false }); return id; },
  run(fn) { return this.runTimeout(fn, 1); },
  runJob(gen) { const id = ++runId; jobs.set(id, gen); return id; },
  clearJob(id) { jobs.delete(id); },
  clearRun(id) { timers.delete(id); },
  afterEvents: { scriptEventReceive: signal() },
  beforeEvents: { startup: signal(), watchdogTerminate: signal(), shutdown: signal() },
};

export async function advance(n = 1) {
  for (let i = 0; i < n; i++) {
    tick++;
    world._time = (world._time + 1) % 24000;
    world._abs++;
    for (const [id, t] of [...timers]) {
      if (!timers.has(id) || t.next > tick) continue;
      try { t.fn(); } catch (e) { log.errors.push(e); console.error('TIMER ERROR', e); }
      if (t.repeat) t.next = tick + t.every; else timers.delete(id);
    }
    for (const [id, g] of [...jobs]) {
      for (let k = 0; k < 50; k++) {
        let r;
        try { r = g.next(); } catch (e) { log.errors.push(e); console.error('JOB ERROR', e); jobs.delete(id); break; }
        if (r.done) { jobs.delete(id); break; }
      }
    }
    await new Promise((r) => setImmediate(r));
  }
}

class Dyn {
  constructor() { this._dp = new Map(); }
  getDynamicProperty(k) { return this._dp.get(k); }
  setDynamicProperty(k, v) { if (v === undefined || v === null) this._dp.delete(k); else { if (typeof v === 'string' && v.length > 32767) throw new Error('too long ' + k); this._dp.set(k, v); } }
  getDynamicPropertyIds() { return [...this._dp.keys()]; }
  clearDynamicProperties() { this._dp.clear(); }
}

export class ItemStack {
  constructor(typeId, amount = 1) {
    if (!typeId || typeof typeId !== 'string') throw new Error('bad item');
    this.typeId = typeId.includes(':') ? typeId : 'minecraft:' + typeId;
    this.amount = amount;
    this.nameTag = undefined;
    this._lore = [];
    this.maxAmount = /sword|axe|pickaxe|grimoire|journal|staff|ring|card|helmet|chestplate|boots|leggings|key/.test(this.typeId) ? 1 : 64;
    this._dur = { damage: 0, maxDurability: 250 };
    this._ench = new Map();
  }
  getLore() { return [...this._lore]; }
  setLore(l) { this._lore = [...(l ?? [])]; }
  clone() { const c = new ItemStack(this.typeId, this.amount); c.nameTag = this.nameTag; c._lore = [...this._lore]; return c; }
  getComponent(id) {
    if (id === 'minecraft:durability' && this.maxAmount === 1) return this._dur;
    if (id === 'minecraft:enchantable' && this.maxAmount === 1) {
      const m = this._ench;
      return {
        getEnchantment: (t) => (m.has(t) ? { type: { id: t }, level: m.get(t) } : undefined),
        canAddEnchantment: () => true,
        addEnchantment: (e) => m.set(e.type.id, e.level),
        removeEnchantment: (t) => m.delete(t),
      };
    }
    return undefined;
  }
}

export class MolangVariableMap { setColorRGB() {} setColorRGBA() {} setFloat() {} setVector3() {} setSpeedAndDirection() {} }
export const EnchantmentTypes = { get: (id) => ({ id, maxLevel: 4 }) };
export const InputPermissionCategory = { Camera: 1, Movement: 2, LateralMovement: 4, Sneak: 5, Jump: 6, Mount: 7, Dismount: 8, MoveForward: 9, MoveBackward: 10, MoveLeft: 11, MoveRight: 12 };
export const EasingType = { Linear: 'Linear', InOutSine: 'InOutSine', OutQuad: 'OutQuad', InQuad: 'InQuad' };
export const EquipmentSlot = { Head: 'Head', Chest: 'Chest', Legs: 'Legs', Feet: 'Feet', Mainhand: 'Mainhand', Offhand: 'Offhand' };
export const GameMode = { Survival: 'Survival', Creative: 'Creative', Adventure: 'Adventure', Spectator: 'Spectator' };
export const TicksPerSecond = 20;
export const TicksPerDay = 24000;

class Container {
  constructor(size) { this.size = size; this.slots = new Array(size).fill(undefined); }
  get emptySlotsCount() { return this.slots.filter((s) => !s).length; }
  getItem(i) { return this.slots[i]; }
  setItem(i, it) { this.slots[i] = it; }
  addItem(it) {
    for (let i = 0; i < this.size; i++) {
      const s = this.slots[i];
      if (s && s.typeId === it.typeId && s.amount < s.maxAmount && !s.nameTag && !it.nameTag) {
        const n = Math.min(it.amount, s.maxAmount - s.amount); s.amount += n; it.amount -= n;
        if (it.amount <= 0) return undefined;
      }
    }
    for (let i = 0; i < this.size; i++) if (!this.slots[i]) { this.slots[i] = it; return undefined; }
    return it;
  }
}

let entCount = 0;
export class Entity extends Dyn {
  constructor(typeId, loc, dim) {
    super();
    this.typeId = typeId.includes(':') ? typeId : 'minecraft:' + typeId;
    this.id = String(-(++entCount));
    this.location = { ...loc };
    this.dimension = dim;
    this.isValid = true;
    this.nameTag = '';
    this._tags = new Set();
    this._props = {};
    this._effects = new Map();
    this._events = [];
    this._hp = { cur: 20, max: 20 };
    this._rot = { x: 0, y: 0 };
    this.isSneaking = false;
    this.isOnGround = true;
    this.isFalling = false;
    this.isJumping = false;
    this.isSwimming = false;
    this.isInWater = false;
    this.isGliding = false;
    this.isFlying = false;
    this.isSleeping = false;
    this._families = typeId.includes('zombie') || typeId.includes('rpg:goblin') ? ['monster'] : [];
  }
  addTag(t) { this._tags.add(t); return true; }
  hasTag(t) { return this._tags.has(t); }
  removeTag(t) { return this._tags.delete(t); }
  getTags() { return [...this._tags]; }
  setProperty(k, v) { this._props[k] = v; }
  getProperty(k) { return this._props[k]; }
  resetProperty(k) { delete this._props[k]; }
  triggerEvent(e) { this._events.push(e); if (e === 'rpg:spawn_guard' || e === 'rpg:guard') this._families.push('rpg_guard'); }
  addEffect(id, dur, opts) { if (dur < 1 || dur > 20000000) throw new Error('dur'); this._effects.set(id, { typeId: id, duration: dur, amplifier: opts?.amplifier ?? 0 }); }
  getEffect(id) { return this._effects.get(id); }
  getEffects() { return [...this._effects.values()]; }
  removeEffect(id) { return this._effects.delete(id); }
  applyDamage(n, opts) {
    const ev = { hurtEntity: this, damage: n, damageSource: { cause: opts?.cause ?? 'none', damagingEntity: opts?.damagingEntity }, cancel: false };
    world.beforeEvents.entityHurt.fire(ev);
    if (ev.cancel) return false;
    this._hp.cur -= ev.damage;
    world.afterEvents.entityHurt.fire({ hurtEntity: this, damage: ev.damage, damageSource: ev.damageSource });
    if (this._hp.cur <= 0) this._die(opts);
    return true;
  }
  _die(opts) {
    if (!this.isValid) return;
    this._hp.cur = 0; this.isValid = false;
    world.afterEvents.entityDie.fire({ deadEntity: this, damageSource: { cause: opts?.cause ?? 'none', damagingEntity: opts?.damagingEntity } });
    if (this.typeId !== 'minecraft:player') this.dimension._ents.delete(this);
    else { this.isValid = true; this._hp.cur = this._hp.max; }
  }
  applyKnockback(a, b) { if (typeof a !== 'object') throw new TypeError('new signature expected'); this._kb = [a, b]; }
  applyImpulse(v) { this._imp = v; }
  clearVelocity() {}
  getVelocity() { return { x: 0, y: 0, z: 0 }; }
  getComponent(id) {
    const e = this;
    if (id === 'minecraft:health') {
      return { get currentValue() { return e._hp.cur; }, get effectiveMax() { return e._hp.max; }, get defaultValue() { return e._hp.max; }, setCurrentValue(v) { e._hp.cur = v; if (v <= 0) e._die({}); return true; }, resetToMaxValue() { e._hp.cur = e._hp.max; } };
    }
    if (id === 'minecraft:inventory' && this._inv) return { container: this._inv };
    if (id === 'minecraft:equippable') return { getEquipment: () => undefined, setEquipment: () => true };
    if (id === 'minecraft:type_family') return { hasTypeFamily: (f) => e._families.includes(f), getTypeFamilies: () => [...e._families] };
    if (id === 'minecraft:projectile') return { owner: e._owner };
    return undefined;
  }
  hasComponent(id) { return !!this.getComponent(id); }
  teleport(loc, opts) { this.location = { ...loc }; if (opts?.dimension) this.dimension = opts.dimension; }
  tryTeleport(loc, opts) { this.teleport(loc, opts); return true; }
  remove() { this.isValid = false; this.dimension._ents.delete(this); }
  kill() { this._die({}); return true; }
  lookAt(l) { const dx = l.x - this.location.x; const dz = l.z - this.location.z; this._view = { x: dx / (Math.hypot(dx, dz) || 1), y: 0, z: dz / (Math.hypot(dx, dz) || 1) }; }
  setRotation(r) { this._rot = r; }
  getRotation() { return this._rot; }
  setOnFire() { return true; }
  extinguishFire() { return true; }
  getHeadLocation() { return { x: this.location.x, y: this.location.y + 1.6, z: this.location.z }; }
  getViewDirection() { return this._view ?? { x: 0, y: 0, z: 1 }; }
  getEntitiesFromViewDirection(o) {
    const dir = this.getViewDirection();
    const out = [];
    for (const e of this.dimension._ents) {
      if (e === this || !e.isValid) continue;
      const v = { x: e.location.x - this.location.x, y: 0, z: e.location.z - this.location.z };
      const d = Math.hypot(v.x, v.z);
      if (d > (o?.maxDistance ?? 50) || d === 0) continue;
      if ((v.x * dir.x + v.z * dir.z) / d > 0.95) out.push({ entity: e, distance: d });
    }
    return out.sort((a, b) => a.distance - b.distance);
  }
  getBlockFromViewDirection() { return undefined; }
  matches() { return true; }
  playAnimation() {}
  runCommand(c) { log.commands.push(c); return { successCount: 1 }; }
}

class Camera {
  constructor(p) { this.p = p; this.calls = []; }
  setCamera(preset, opts) { this.calls.push(['set', preset, opts]); }
  fade(opts) { this.calls.push(['fade', opts]); }
  clear() { this.calls.push(['clear']); }
  setFov() {}
}

export class Player extends Entity {
  constructor(name, dim) {
    super('minecraft:player', { x: 0.5, y: 65, z: 0.5 }, dim);
    this.name = name;
    this.selectedSlotIndex = 0;
    this._inv = new Container(36);
    this._ab = '';
    this.onScreenDisplay = {
      setActionBar: (t) => { this._ab = Array.isArray(t) ? t.join('') : t; },
      setTitle: (t, o) => { this._title = t; this._subtitle = o?.subtitle; },
      updateSubtitle: (t) => { this._subtitle = t; },
      resetHudElements: () => {}, setHudVisibility: () => {}, isValid: true,
    };
    this.camera = new Camera(this);
    const perms = {};
    this.inputPermissions = {
      setPermissionCategory: (c, v) => { perms[c] = v; },
      isPermissionCategoryEnabled: (c) => perms[c] !== false,
      _perms: perms,
    };
    this.playerPermissionLevel = 2;
    this._msgs = [];
  }
  sendMessage(m) { const s = typeof m === 'string' ? m : JSON.stringify(m); this._msgs.push(s); log.messages.push(`[${this.name}] ${s}`); }
  playSound() {}
  setSpawnPoint(p) { this._spawn = p; }
  getSpawnPoint() { return this._spawn; }
  getGameMode() { return 'Survival'; }
  setGameMode() {}
  spawnParticle(id) { log.particles++; log.particleIds[id] = (log.particleIds[id] ?? 0) + 1; }
  startItemCooldown() {}
  getItemCooldown() { return 0; }
}

class Block {
  constructor(dim, loc, typeId) { this.dimension = dim; this.location = loc; this.typeId = typeId; this.x = loc.x; this.y = loc.y; this.z = loc.z; }
  get isAir() { return this.typeId === 'minecraft:air'; }
  get isLiquid() { return this.typeId.includes('water') || this.typeId.includes('lava'); }
  get isValid() { return true; }
  get permutation() { const b = this; return { getState: () => undefined, withState: () => b.permutation, matches: (t) => t === b.typeId, type: { id: b.typeId } }; }
  get type() { return { id: this.typeId }; }
  getComponent(id) { if (id === 'minecraft:inventory' && this.typeId.includes('chest') || id === 'minecraft:inventory' && this.typeId.includes('barrel')) return { container: (this._c ??= new Container(27)) }; }
  setPermutation() {}
  setType(t) { this.typeId = t.includes(':') ? t : 'minecraft:' + t; }
  above(n = 1) { return this.dimension.getBlock({ x: this.x, y: this.y + n, z: this.z }); }
  below(n = 1) { return this.dimension.getBlock({ x: this.x, y: this.y - n, z: this.z }); }
  center() { return { x: this.x + 0.5, y: this.y + 0.5, z: this.z + 0.5 }; }
  bottomCenter() { return { x: this.x + 0.5, y: this.y, z: this.z + 0.5 }; }
}

class Dimension {
  constructor(id) { this.id = id; this._ents = new Set(); this._blocks = new Map(); this.heightRange = { min: -64, max: 320 }; }
  getBlock(l) {
    const k = `${Math.floor(l.x)},${Math.floor(l.y)},${Math.floor(l.z)}`;
    if (this._blocks.has(k)) return this._blocks.get(k);
    const y = Math.floor(l.y);
    const t = y < 64 ? 'minecraft:stone' : y === 64 ? 'minecraft:grass_block' : 'minecraft:air';
    const b = new Block(this, { x: Math.floor(l.x), y, z: Math.floor(l.z) }, t);
    this._blocks.set(k, b);
    return b;
  }
  setBlockType(l, t) { this.getBlock(l).setType(t); }
  getTopmostBlock(l) { return this.getBlock({ x: l.x, y: 64, z: l.z }); }
  getBlockFromRay(loc, dir, opts) {
    const max = opts?.maxDistance ?? 64;
    for (let d = 0.5; d < max; d += 0.5) {
      const p = { x: loc.x + dir.x * d, y: loc.y + dir.y * d, z: loc.z + dir.z * d };
      const b = this.getBlock(p);
      if (b && !b.isAir && !b.isLiquid) return { block: b, face: 'Up', faceLocation: { x: 0.5, y: 1, z: 0.5 } };
    }
    return undefined;
  }
  getEntitiesFromRay() { return []; }
  getLightLevel(l) { return world._time > 13000 ? 4 : 15; }
  getSkyLightLevel() { return 15; }
  isChunkLoaded() { return true; }
  getEntities(o = {}) {
    let list = [...this._ents].filter((e) => e.isValid);
    if (o.type) list = list.filter((e) => e.typeId === (o.type.includes(':') ? o.type : 'minecraft:' + o.type));
    if (o.excludeTypes) list = list.filter((e) => !o.excludeTypes.includes(e.typeId));
    if (o.tags) list = list.filter((e) => o.tags.every((t) => e.hasTag(t)));
    if (o.excludeTags) list = list.filter((e) => !o.excludeTags.some((t) => e.hasTag(t)));
    if (o.families) list = list.filter((e) => o.families.every((f) => e._families.includes(f)));
    if (o.excludeFamilies) list = list.filter((e) => !o.excludeFamilies.some((f) => e._families.includes(f)));
    if (o.location && o.maxDistance !== undefined) list = list.filter((e) => Math.hypot(e.location.x - o.location.x, e.location.y - o.location.y, e.location.z - o.location.z) <= o.maxDistance);
    if (o.location && o.closest) list = list.sort((a, b) => Math.hypot(a.location.x - o.location.x, a.location.z - o.location.z) - Math.hypot(b.location.x - o.location.x, b.location.z - o.location.z)).slice(0, o.closest);
    return list;
  }
  getPlayers(o) { return this.getEntities({ ...(o ?? {}), type: 'minecraft:player' }); }
  spawnEntity(type, loc) {
    const m = /^(.*?)(?:<(.+)>)?$/.exec(type);
    type = m[1];
    const e = new Entity(type, loc, this);
    if (m[2]) e.triggerEvent(m[2]);
    if (type.startsWith('rpg:') && /king|queen|golem|lich|lord|dragon/.test(type)) { e._families.push('rpg_boss', 'monster'); e._hp = { cur: 300, max: 300 }; }
    if (['rpg:goblin', 'rpg:orc', 'rpg:troll', 'rpg:mimic'].includes(type)) e._families.push('monster');
    if (type === 'rpg:npc') e._families.push('npc', 'rpg_npc');
    this._ents.add(e);
    world.afterEvents.entitySpawn.fire({ entity: e, cause: 'Spawned' });
    return e;
  }
  spawnItem(it, loc) { const e = new Entity('minecraft:item', loc, this); e._item = it; this._ents.add(e); return e; }
  spawnParticle(id) { log.particles++; log.particleIds[id] = (log.particleIds[id] ?? 0) + 1; }
  playSound() {}
  runCommand(c) {
    log.commands.push(c);
    const m = /^(setblock|fill) (-?\d+) (-?\d+) (-?\d+)(?: (-?\d+) (-?\d+) (-?\d+))? (\S+)/.exec(c);
    if (m && m[1] === 'setblock') this.getBlock({ x: +m[2], y: +m[3], z: +m[4] }).setType(m[8]);
    return { successCount: 1 };
  }
  createExplosion() { return true; }
  setWeather() {}
}

const dims = { overworld: new Dimension('minecraft:overworld'), nether: new Dimension('minecraft:nether'), the_end: new Dimension('minecraft:the_end') };

class World extends Dyn {
  constructor() {
    super();
    this._time = 1000;
    this._abs = 0;
    this._players = [];
    const names = ['worldLoad', 'playerSpawn', 'playerJoin', 'playerLeave', 'itemUse', 'itemCompleteUse', 'itemStartUse', 'itemReleaseUse', 'itemStopUse', 'entityHurt', 'entityDie', 'entityHitEntity',
      'playerBreakBlock', 'playerPlaceBlock', 'entitySpawn', 'entityLoad', 'entityRemove', 'playerInteractWithEntity', 'playerInteractWithBlock', 'projectileHitEntity', 'projectileHitBlock', 'weatherChange',
      'playerButtonInput', 'entityHealthChanged', 'dataDrivenEntityTrigger', 'playerDimensionChange', 'effectAdd', 'buttonPush', 'leverAction', 'pressurePlatePush', 'targetBlockHit', 'tripWireTrip', 'playerEmote', 'playerGameModeChange'];
    this.afterEvents = Object.fromEntries(names.map((n) => [n, signal()]));
    const before = ['playerLeave', 'playerInteractWithEntity', 'playerInteractWithBlock', 'itemUse', 'playerBreakBlock', 'entityHurt', 'entityRemove', 'explosion', 'effectAdd', 'weatherChange', 'playerGameModeChange', 'entityItemPickup'];
    this.beforeEvents = Object.fromEntries(before.map((n) => [n, signal()]));
    const areas = new Map();
    this.tickingAreaManager = {
      createTickingArea: async (id, opts) => { areas.set(id, opts); return { identifier: id, ...opts }; },
      removeTickingArea: (id) => areas.delete(typeof id === 'string' ? id : id.identifier),
      hasTickingArea: (id) => areas.has(id),
      getAllTickingAreas: () => [...areas.keys()],
      maxChunkCount: 2000, chunkCount: 0, _areas: areas,
    };
    this.gameRules = {};
    this.seed = '12345';
  }
  getDay() { return Math.floor(this._abs / 24000) + (this._dayOffset ?? 0); }
  getTimeOfDay() { return this._time; }
  setTimeOfDay(t) { this._time = t; }
  getAbsoluteTime() { return this._abs; }
  getMoonPhase() { return 0; }
  getAllPlayers() { return this._players.filter((p) => p.isValid); }
  getPlayers() { return this.getAllPlayers(); }
  getDimension(id) { return dims[id.replace('minecraft:', '')]; }
  getEntity(id) { for (const d of Object.values(dims)) for (const e of d._ents) if (e.id === id) return e; return undefined; }
  getDefaultSpawnLocation() { return { x: 0, y: 32767, z: 0 }; }
  sendMessage(m) { log.messages.push('[WORLD] ' + (typeof m === 'string' ? m : JSON.stringify(m))); }
  playSound() {}
  addPlayer(name) { const p = new Player(name, dims.overworld); this._players.push(p); dims.overworld._ents.add(p); return p; }
}

export const world = new World();
